(284, 'shambling-mound', 'Shambling Mound', 'Ползающая насыпь', 'large', 'plant', 15, 136, '16d10', 'walk 20 ft., swim 20 ft.', 8, 5, '5', 1800, '["cold","fire"]', '["lightning"]', '[]', '["blinded","blinded","exhaustion"]', '[{"name":"Multiattack","desc":"The shambling mound makes two slam attacks. If both attacks hit a Medium or smaller target, the target is grappled (escape DC 14), and the shambling mound uses its Engulf on it."},{"name":"Slam","desc":"Melee Weapon Attack: +7 to hit, reach 5 ft., one target. Hit: 13 (2d8 + 4) bludgeoning damage.","attack_bonus":7,"damage":"2d8+4 bludgeoning"},{"name":"Engulf","desc":"The shambling mound engulfs a Medium or smaller creature grappled by it. The engulfed target is blinded, restrained, and unable to breathe, and it must succeed on a DC 14 Constitution saving throw at the start of each of the mound''s turns or take 13 (2d8 + 4) bludgeoning damage. If the mound moves, the engulfed target moves with it. The mound can have only one creature engulfed at a time."}]', 'Lightning Absorption. Whenever the shambling mound is subjected to lightning damage, it takes no damage and regains a number of hit points equal to the lightning damage dealt.', 'https://www.dnd5eapi.co/api/2014/monsters/shambling-mound', 'https://5e14.dnd.su/bestiary/284-shambling-mound/', 0),
