(298, 'sprite', 'Sprite', 'Спрайт', 'tiny', 'fey', 15, 2, '1d4', 'walk 10 ft., fly 40 ft.', 18, 0.25, '1/4', 50, '[]', '[]', '[]', '[]', '[{"name":"Longsword","desc":"Melee Weapon Attack: +2 to hit, reach 5 ft., one target. Hit: 1 slashing damage.","attack_bonus":2,"damage":"1 slashing"},{"name":"Shortbow","desc":"Ranged Weapon Attack: +6 to hit, range 40/160 ft., one target. Hit: 1 piercing damage, and the target must succeed on a DC 10 Constitution saving throw or become poisoned for 1 minute. If its saving throw result is 5 or lower, the poisoned target falls unconscious for the same duration, or until it takes damage or another creature takes an action to shake it awake.","attack_bonus":6,"damage":"1 piercing"},{"name":"Heart Sight","desc":"The sprite touches a creature and magically knows the creature''s current emotional state. If the target fails a DC 10 Charisma saving throw, the sprite also knows the creature''s alignment. Celestials, fiends, and undead automatically fail the saving throw."},{"name":"Invisibility","desc":"The sprite magically turns invisible until it attacks or casts a spell, or until its concentration ends (as if concentrating on a spell). Any equipment the sprite wears or carries is invisible with it."}]', '', 'https://www.dnd5eapi.co/api/2014/monsters/sprite', 'https://5e14.dnd.su/bestiary/298-sprite/', 0),
